          />
        </label>{' '}
        <span>
          now:{' '}
          <strong data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</strong>
        </span>{' '}
        <label>
          Grace days{' '}
          <input
